<style>
.framer-nzj1qu-container{display:none!important}html{scroll-padding-top:110px}.rm-header,.rm-header *{box-sizing:border-box}.rm-header{--surface:#fff;--ink:#303030;--hover:#fff0f0;position:sticky;top:0;z-index:10000;background:var(--surface);color:var(--ink);border-bottom:1px solid #e5e5e5;font:500 14px/1.4 Arial,sans-serif;box-shadow:0 4px 20px #00000008}.rm-header[data-style="dark"]{--surface:#252525;--ink:#f5f5f5;--hover:#414141;border-bottom:3px solid #d70000}.rm-wrap{max-width:1240px;margin:auto;min-height:100px;padding:8px 24px;display:flex;align-items:center;gap:28px}.rm-logo{display:flex;flex-shrink:0;background:#fff;border-radius:7px;padding:3px 8px}.rm-logo img{width:136px;height:80px;object-fit:contain}.rm-nav{display:flex;align-items:center;gap:5px;margin-left:auto}.rm-nav a,.rm-drop>button{display:block;padding:12px 14px;border:0;border-radius:7px;color:var(--ink);background:transparent;font:inherit;text-decoration:none;cursor:pointer;white-space:nowrap;transition:background .18s,color .18s}.rm-nav a:hover,.rm-drop>button:hover{background:var(--hover);color:#d70000}.rm-nav a[aria-current="page"],.rm-drop>button.rm-active{color:#d70000;background:var(--hover);font-weight:700}.rm-header[data-style="dark"] .rm-nav a[aria-current="page"],.rm-header[data-style="dark"] .rm-drop>button.rm-active{background:#d70000;color:#fff}.rm-header :focus-visible{outline:3px solid #f15b5b;outline-offset:3px}.rm-drop{position:relative}.rm-drop>button span{display:inline-block;margin-left:6px;transition:transform .18s}.rm-drop>button[aria-expanded="true"] span{transform:rotate(180deg)}.rm-sub{position:absolute;top:100%;left:0;min-width:210px;padding:8px;background:var(--surface);border:1px solid #8884;border-radius:10px;box-shadow:0 14px 35px #0002}.rm-sub[hidden]{display:none}.rm-sub a{padding:12px}.rm-switch,.rm-toggle{padding:10px 12px;border:1px solid #8886;border-radius:7px;background:transparent;color:var(--ink);font:inherit;cursor:pointer}.rm-switch:hover,.rm-toggle:hover{background:var(--hover)}.rm-toggle{display:none}.rm-header[data-style="dark"] .rm-nav a:hover,.rm-header[data-style="dark"] .rm-drop>button:hover{color:#ff7777}@media(max-width:900px){.rm-wrap{flex-wrap:wrap;gap:10px;padding:8px 16px;min-height:90px}.rm-logo img{width:115px;height:68px}.rm-switch{margin-left:auto;font-size:12px}.rm-toggle{display:block}.rm-nav{display:none;width:100%;margin:0;align-items:stretch;flex-direction:column;padding:8px 0}.rm-nav.rm-open{display:flex}.rm-drop>button{width:100%;text-align:left}.rm-sub{position:static;box-shadow:none;margin:3px 12px}.rm-nav a{width:100%}}@media(prefers-reduced-motion:reduce){.rm-header *{transition:none!important}}
</style>
<link rel="stylesheet" href="./assets/menu-icons.css">
<header class="rm-header" data-style="light" id="rm-header">
<div class="rm-wrap">
<a class="rm-logo" href="./" aria-label="Royalmark Estate home"><img src="./assets/royalmark-logo.png" alt="Royalmark Estate" width="136" height="80"></a>
<button class="rm-switch" type="button" aria-label="Switch to charcoal menu style"><span class="rm-style-label">Style: Light</span> <svg class="rm-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9"/><path d="M12 3a9 9 0 0 1 0 18z" fill="currentColor"/></svg></button>
<button class="rm-toggle" type="button" aria-controls="rm-nav" aria-expanded="false"><svg class="rm-icon rm-bars" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 6h16M4 12h16M4 18h16"/></svg><svg class="rm-icon rm-close" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m6 6 12 12M18 6 6 18"/></svg>Menu</button>
<nav class="rm-nav" id="rm-nav" aria-label="Main navigation">
<a href="./" data-route="home" aria-current="page"><svg class="rm-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/></svg>Home</a>
<a href="./property-listing" data-route="properties"><svg class="rm-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>Properties</a>
<div class="rm-drop"><button type="button" aria-expanded="false" aria-controls="rm-buy"><svg class="rm-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m3 3 8 1 10 10-7 7L4 11z"/><circle cx="8" cy="8" r="1"/></svg>Buy <svg class="rm-icon rm-chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m6 9 6 6 6-6"/></svg></button><div class="rm-sub" id="rm-buy" hidden><a href="./property-listing?listing-purpose=sell&amp;property-types=apartment">Apartments for sale</a><a href="./property-listing?listing-purpose=sell&amp;property-types=independent-house">Houses for sale</a><a href="./property-listing?listing-purpose=sell&amp;property-types=villa">Villas for sale</a></div></div>
<div class="rm-drop"><button type="button" aria-expanded="false" aria-controls="rm-rent"><svg class="rm-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><circle cx="8" cy="8" r="5"/><path d="m11.5 11.5 9 9M15 15l3-3M18 18l3-3"/></svg>Rent <svg class="rm-icon rm-chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m6 9 6 6 6-6"/></svg></button><div class="rm-sub" id="rm-rent" hidden><a href="./property-listing?listing-purpose=rent&amp;property-types=apartment">Apartments for rent</a><a href="./property-listing?listing-purpose=rent&amp;property-types=independent-house">Houses for rent</a><a href="./property-listing?listing-purpose=rent&amp;property-types=villa">Villas for rent</a></div></div>
<a href="./about-us" data-route="about"><svg class="rm-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/></svg>About</a><a href="./blog" data-route="blog"><svg class="rm-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 8h10M7 12h10M7 16h6"/></svg>Blog</a>
</nav></div></header>
<script>
(()=>{'use strict';const header=document.getElementById('rm-header'),nav=document.getElementById('rm-nav'),toggle=header.querySelector('.rm-toggle'),switcher=header.querySelector('.rm-switch'),drops=[...header.querySelectorAll('.rm-drop')];
function style(value){header.dataset.style=value;switcher.querySelector('.rm-style-label').textContent=value==='dark'?'Style: Charcoal':'Style: Light';switcher.setAttribute('aria-label',value==='dark'?'Switch to light menu style':'Switch to charcoal menu style')}
try{style(localStorage.getItem('royalmark-menu-style')==='dark'?'dark':'light')}catch(e){}
switcher.addEventListener('click',()=>{style(header.dataset.style==='dark'?'light':'dark');try{localStorage.setItem('royalmark-menu-style',header.dataset.style)}catch(e){}});
function close(except){drops.forEach(drop=>{if(drop!==except){drop.querySelector('button').setAttribute('aria-expanded','false');drop.querySelector('.rm-sub').hidden=true}})}
drops.forEach(drop=>{const button=drop.querySelector('button'),panel=drop.querySelector('.rm-sub');function open(){close(drop);button.setAttribute('aria-expanded','true');panel.hidden=false}button.addEventListener('click',e=>{if(e.detail>0&&matchMedia('(hover:hover) and (min-width:901px)').matches){open();return;}const expanded=button.getAttribute('aria-expanded')==='true';close();if(!expanded)open()});button.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();open();panel.querySelector('a').focus()}});drop.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&matchMedia('(min-width:901px)').matches)open()});drop.addEventListener('pointerleave',()=>{if(!drop.contains(document.activeElement)){button.setAttribute('aria-expanded','false');panel.hidden=true}});drop.addEventListener('focusout',()=>{setTimeout(()=>{if(!drop.contains(document.activeElement)){button.setAttribute('aria-expanded','false');panel.hidden=true}},0)});panel.addEventListener('keydown',e=>{const links=[...panel.querySelectorAll('a')],index=links.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();links[(index+(e.key==='ArrowDown'?1:-1)+links.length)%links.length].focus()}})});
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('rm-open',open);if(!open)close()});document.addEventListener('click',e=>{if(!header.contains(e.target)){close();nav.classList.remove('rm-open');toggle.setAttribute('aria-expanded','false')}});header.addEventListener('keydown',e=>{if(e.key==='Escape'){const active=drops.find(drop=>drop.querySelector('button').getAttribute('aria-expanded')==='true');close();if(active)active.querySelector('button').focus();else{nav.classList.remove('rm-open');toggle.setAttribute('aria-expanded','false');toggle.focus()}}});
const path=location.pathname.replace(/\/$/,''),purpose=new URLSearchParams(location.search).get('listing-purpose');let route=path.endsWith('/about-us')?'about':path.endsWith('/blog')?'blog':path.includes('/property-listing')?'properties':'home';nav.querySelectorAll('[aria-current]').forEach(a=>a.removeAttribute('aria-current'));if(route==='properties'&&purpose){const panel=document.getElementById(purpose==='rent'?'rm-rent':'rm-buy');panel.previousElementSibling.classList.add('rm-active');const current=[...panel.querySelectorAll('a')].find(a=>new URL(a.href).search===location.search);if(current)current.setAttribute('aria-current','page')}else nav.querySelector('[data-route="'+route+'"]').setAttribute('aria-current','page');
matchMedia('(min-width:901px)').addEventListener('change',()=>{close();nav.classList.remove('rm-open');toggle.setAttribute('aria-expanded','false')});})();
</script>
